import { Transform, Type } from 'class-transformer';
import {
  ArrayMaxSize,
  IsArray,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Matches,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import { MAX_ATTACHMENTS_PER_MESSAGE } from './chat.constants.js';

const trim = ({ value }: { value: unknown }) =>
  typeof value === 'string' ? value.trim() : value;

const BIGINT_ID = /^\d{1,19}$/;

export class SendMessageDto {
  @IsOptional()
  @Transform(trim)
  @IsString()
  @MaxLength(2000)
  content?: string;

  /** generated by the client, so a retry never creates the same message twice */
  @IsOptional()
  @IsUUID()
  clientMessageId?: string;

  /** ids returned by POST /chat/conversations/:id/uploads */
  @IsOptional()
  @IsArray()
  @ArrayMaxSize(MAX_ATTACHMENTS_PER_MESSAGE)
  @IsUUID(undefined, { each: true })
  attachmentIds?: string[];
}

export class MarkReadDto {
  @Matches(BIGINT_ID, { message: 'lastReadMessageId must be a message id' })
  lastReadMessageId: string;
}

export class ListMessagesQueryDto {
  /** older messages: returns messages with id < before (newest first) */
  @IsOptional()
  @Matches(BIGINT_ID, { message: 'before must be a message id' })
  before?: string;

  /** sync after a reconnect: returns messages with id > after (oldest first) */
  @IsOptional()
  @Matches(BIGINT_ID, { message: 'after must be a message id' })
  after?: string;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  limit?: number;
}

export class ListConversationsQueryDto {
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(50)
  limit?: number;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(0)
  offset?: number;
}

// ------------------------------------------------------------ WebSocket payloads

export class JoinConversationDto {
  @IsUUID()
  conversationId: string;
}

export class WsSendMessageDto extends SendMessageDto {
  @IsUUID()
  conversationId: string;
}

export class WsMarkReadDto extends MarkReadDto {
  @IsUUID()
  conversationId: string;
}
